let calls = 0;
let bytesReads = 0;
let textReads = 0;
let itemsReads = 0;
export function make(empty) {
  calls++;
  return {
    get bytes() { bytesReads++; return process.argv.includes("--lie") ? [] : new Uint8Array(empty ? [] : [1, 2, 3]); },
    get text() { textReads++; return "hi😀"; },
    get items() { itemsReads++; return ["a", "b"]; },
  };
}
export function counts() { return `${calls}:${bytesReads}:${textReads}:${itemsReads}`; }
